        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            byte b2 = bb.get();
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
            i += 2;
