static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Calculate the day of the month to round down to
    int newDay = (day / dayStep) * dayStep + 1;

    // Adjust for the case where the new day is beyond the last day of the month
    int[] daysInMonth = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (month == 2 && (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0))) {
        daysInMonth[1] = 29; // Leap year
    }
    if (newDay > daysInMonth[month - 1]) {
        newDay = daysInMonth[month - 1];
    }

    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            size += 4; // surrogate pair takes 4 bytes in UTF-8
        } else {
            size += 3;
        }
    }
    return size;
}

