public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    int utfLen = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x0080) {
            utfLen++;
        } else if (c < 0x0800) {
            utfLen += 2;
        } else if (c < 0xD800 || c >= 0xE000) {
            utfLen += 3;
        } else {
            i++;
        }
    }

    byte[] bytes = new byte[utfLen];
    int result = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x0080) {
            bytes[result++] = (byte) c;
        } else if (c < 0x0800) {
            bytes[result++] = (byte) (0xC0 | (c >> 6));
            bytes[result++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c >= 0xE000) {
            bytes[result++] = (byte) (0xE0 | (c >> 12));
            bytes[result++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[result++] = (byte) (0x80 | (c & 0x3F));
        } else {
            i++;
        }
    }

    return lb.buffer(bytes);
}

