private void pop(final String descriptor){
    // Assuming the descriptor is a type descriptor
    if (descriptor.length() == 1) {
        // Basic types and return address
        outputFrameStack.pop();
    } else if (descriptor.startsWith("[")) {
        // Array type
        outputFrameStack.pop();
    } else if (descriptor.startsWith("L")) {
        // Object type
        outputFrameStack.pop();
    } else if (descriptor.startsWith("(")) {
        // Method descriptor, pop argument types
        int index = 1;
        while (descriptor.charAt(index) != ')') {
            char c = descriptor.charAt(index);
            if (c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
                // Single slot types
                outputFrameStack.pop();
            } else if (c == '[') {
                // Array type, single slot
                outputFrameStack.pop();
                // Skip array signature
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                if (descriptor.charAt(index) == 'L') {
                    // Object in array, skip to end of object descriptor
                    index = descriptor.indexOf(';', index) + 1;
                } else {
                    index++;
                }
            } else if (c == 'L') {
                // Object type, single slot
                outputFrameStack.pop();
                // Skip to end of object descriptor
                index = descriptor.indexOf(';', index) + 1;
            }
        }
    }
}

